    static int Main(string[] args){string root=Path.GetFullPath(args[0]),dir=Path.Combine(root,"re/campaigns/C001/perfect-circle");using var manifest=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(dir,"manifest.json")));int admitted=0,rejected=0;string temp=Path.Combine(Path.GetTempPath(),"pqa-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
