      File.WriteAllText(file,Map(first+"\n98,104,1100,1,0",.5f));C(Near(Beatmap.LoadCanonical(file).Circles.Single().Position,new Vector2(98,104)-delta),"negative stack uses adjusted P final endpoint");File.WriteAllText(file,Map(first.Replace(",1,12",",2,12")+"\n106,100,1300,1,0",.5f));C(Near(Beatmap.LoadCanonical(file).Circles.Single().Position,new Vector2(106,100)-delta),"even-repeat tail stack uses traversal endpoint at head");
